package com.medcore.backend.api.infraestructura.habitaciones;import jakarta.persistence.*;
@Entity@Table(name="habitaciones") public class Habitacion{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true,length=20)private String numero;@Column(nullable=false,length=100)private String sector;@Column(nullable=false)private Integer piso;@Column(nullable=false,length=20)private String estado="ACTIVA";public Long getId(){return id;}public void setId(Long v){id=v;}public String getNumero(){return numero;}public void setNumero(String v){numero=v;}public String getSector(){return sector;}public void setSector(String v){sector=v;}public Integer getPiso(){return piso;}public void setPiso(Integer v){piso=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;}}
